<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: '.route_url('explore'));exit;}verify_csrf();$user=current_user();$action=$_POST['action']??'';$return=trim((string)($_POST['return']??'dashboard'));
if($action==='follow'){$creator=(int)($_POST['creator_id']??0);if($creator&&$creator!==(int)$user['id']){$stmt=$pdo->prepare('SELECT COUNT(*) FROM follows WHERE follower_id=? AND creator_id=?');$stmt->execute([$user['id'],$creator]);if($stmt->fetchColumn())$pdo->prepare('DELETE FROM follows WHERE follower_id=? AND creator_id=?')->execute([$user['id'],$creator]);else $pdo->prepare('INSERT INTO follows(follower_id,creator_id) VALUES(?,?)')->execute([$user['id'],$creator]);}}
else{$template=(int)($_POST['template_id']??0);if($action==='like'||$action==='favorite'){$table=$action==='like'?'template_likes':'template_favorites';$stmt=$pdo->prepare("SELECT COUNT(*) FROM {$table} WHERE user_id=? AND template_id=?");$stmt->execute([$user['id'],$template]);if($stmt->fetchColumn())$pdo->prepare("DELETE FROM {$table} WHERE user_id=? AND template_id=?")->execute([$user['id'],$template]);else $pdo->prepare("INSERT INTO {$table}(user_id,template_id) VALUES(?,?)")->execute([$user['id'],$template]);}elseif($action==='rating'){$rating=max(1,min(5,(int)($_POST['rating']??5)));$pdo->prepare('INSERT INTO template_ratings(user_id,template_id,rating) VALUES(?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating)')->execute([$user['id'],$template,$rating]);}elseif($action==='report'){$reason=trim((string)($_POST['reason']??''));if($reason!=='')$pdo->prepare('INSERT INTO reports(reporter_id,template_id,reason) VALUES(?,?,?)')->execute([$user['id'],$template,$reason]);}}
header('Location: '.route_url($return));exit;
